# Compare data/myv_arth.csv regenerated by scripts/00-clean-data-round1.R
# against the previous committed version (commit 7b096d8). Run from project root:
#   git show 7b096d8:data/myv_arth.csv > old.csv  (any temporary path)
#   Rscript review/23-compare-myv-arth.R old.csv > review/23-compare-myv-arth-output.txt 2>&1

suppressPackageStartupMessages(library(tidyverse))
old_path <- commandArgs(TRUE)[1]
rd <- \(x) suppressMessages(read_csv(x, show_col_types = FALSE))
old <- rd(old_path); new <- rd("data/myv_arth.csv")
key <- c("trans", "dist", "year", "taxon")
cat("Rows: old", nrow(old), "| new", nrow(new), "\n")
cat("Columns identical:", identical(names(old), names(new)), "\n")
cat("Duplicate keys in new:", sum(duplicated(new[key])), "\n")
cat("Rows only in old:", nrow(anti_join(old, new, by = key)),
    "| only in new:", nrow(anti_join(new, old, by = key)), "\n\n")
j <- inner_join(old, new, by = key, suffix = c(".old", ".new"))
vals <- setdiff(names(new), key)
chg <- map(vals, \(v) {
    a <- j[[paste0(v, ".old")]]; b <- j[[paste0(v, ".new")]]
    bad <- xor(is.na(a), is.na(b)) | (!is.na(a) & !is.na(b) & a != b)
    tibble(column = v, rows_changed = sum(bad),
           years = paste(sort(unique(j$year[bad])), collapse = " "))
}) |> list_rbind()
cat("Changed values by column (rows of trans x dist x year x taxon):\n")
print(chg, n = Inf, width = Inf)
cat("\nSite-years changed (any column):\n")
anybad <- reduce(map(vals, \(v) {
    a <- j[[paste0(v, ".old")]]; b <- j[[paste0(v, ".new")]]
    xor(is.na(a), is.na(b)) | (!is.na(a) & !is.na(b) & a != b)
}), `|`)
j[anybad, ] |> distinct(trans, dist, year) |> count(year) |> print(n = Inf)
cat("\nAnalysed-site rows (5 sites, 5/50/150 m) changed by year:\n")
j[anybad, ] |> filter(trans %in% c("btl","hag","kal","non","vin"),
                      dist %in% c(5, 50, 150)) |>
    distinct(trans, dist, year) |> count(year) |> print(n = Inf)

cat("\nRatio new/old by taxon and year, analysed sites (sum over site rows;",
    "count and season_days):\n")
j |> filter(trans %in% c("btl","hag","kal","non","vin"), dist %in% c(5, 50, 150)) |>
    group_by(taxon, year) |>
    summarize(count = round(sum(count.new) / sum(count.old), 2),
              days = round(sum(season_days.new) / sum(season_days.old), 2),
              .groups = "drop") |>
    filter(count != 1 | days != 1) |>
    pivot_wider(names_from = taxon, values_from = c(count, days)) |>
    arrange(year) |>
    print(n = Inf, width = Inf)
cat("\nMidges: ratio new/old by year, analysed sites (one row per site-year):\n")
j |> filter(trans %in% c("btl","hag","kal","non","vin"), dist %in% c(5, 50, 150)) |>
    distinct(trans, dist, year, midges.old, midges.new, midge_days.old, midge_days.new) |>
    group_by(year) |>
    summarize(midges = round(sum(midges.new) / sum(midges.old), 3),
              midge_days = round(sum(midge_days.new) / sum(midge_days.old), 3)) |>
    print(n = Inf)

cat("\n2014 infall samples with no midge count (all sites), by dates:\n")
rd("data/raw/infalls-13-19.csv") |>
    filter(lakeid == "myv", lubridate::year(coldate) == 2014) |>
    mutate(no_count = is.na(bgch / fract_bgch + smch / fract_smch)) |>
    count(setdate, coldate, no_count) |>
    pivot_wider(names_from = no_count, values_from = n, values_fill = 0,
                names_prefix = "no_count_") |>
    print(n = Inf)

cat("\n2017 pitfall samples (analysed sites) by file:\n")
k <- c("lakeid", "dist", "trans", "setdate", "coldate")
pp1 <- rd("data/raw/pitfalls-08-17.csv") |> select(all_of(k))
pp2 <- rd("data/raw/pitfalls-11-19.csv") |> select(all_of(k))
f <- \(d) d |> filter(lakeid == "myv", lubridate::year(coldate) == 2017,
                      trans %in% c("btl","hag","kal","non","vin"), dist %in% c(5, 50, 150))
cat("in 08-17 file:", nrow(f(pp1)), "| in 11-19 file:", nrow(f(pp2)),
    "| in both:", nrow(semi_join(f(pp1), f(pp2), by = k)), "\n")
